// Resolve a wall time using offsets on both sides of a possible transition.
// Repeated times choose the earlier instant; skipped times move forward by the gap.
function wallTime(date: string, hour: number, timeZone: string): Date {
  const [year, month, day] = date.split("-").map(Number);
  const target = Date.UTC(year, month - 1, day, hour);
  const candidates = new Set<number>();
  for (const delta of [-2 * DAY_MS, -DAY_MS, 0, DAY_MS, 2 * DAY_MS]) {
    const sample = target + delta;
    const p = localParts(new Date(sample), timeZone);
    const offset = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - sample;
    candidates.add(target - offset);
  }
  const ranked = [...candidates].map((instant) => {
    const p = localParts(new Date(instant), timeZone);
    return { instant, difference: Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - target };
  });
  const exact = ranked.filter((x) => x.difference === 0).sort((a, b) => a.instant - b.instant);
  if (exact.length) return new Date(exact[0]!.instant);
  const after = ranked.filter((x) => x.difference > 0).sort((a, b) => a.difference - b.difference || a.instant - b.instant);
  return new Date(after[0]!.instant);
}

function shiftDate(date: string, days: number): string {
  const [year, month, day] = date.split("-").map(Number);
  return new Date(Date.UTC(year, month - 1, day + days)).toISOString().slice(0, 10);
